package cn.zhuatech.datamask;import cn.zhuatech.datamask.service.DataMaskService;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class DataMaskServiceTests{private final DataMaskService s=new DataMaskService();@Test void masksPhoneAndEmail(){var r=s.preview(new DataMaskService.Request(List.of(new DataMaskService.Field("phone","PHONE","13812345678"),new DataMaskService.Field("mail","EMAIL","a@zhuatech.cn"))));assertEquals(100.0,r.coverage());assertTrue(r.fields().get(0).maskedValue().contains("****"));}@Test void reportsUnknownType(){assertEquals(1,s.preview(new DataMaskService.Request(List.of(new DataMaskService.Field("x","UNKNOWN","v")))).unsupportedCount());}}
